-- Finance and Procurement module (finance.db)
-- Money records, invoices, payments and purchasing.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE finance_transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        transaction_date TEXT NOT NULL,
        transaction_type TEXT NOT NULL
            CHECK (transaction_type IN ('income', 'expense')),
        category TEXT NOT NULL,
        description TEXT NOT NULL,
        party_name TEXT DEFAULT '',
        employee_id INTEGER,
        currency TEXT NOT NULL DEFAULT 'ETB',
        amount NUMERIC NOT NULL CHECK (amount > 0),
        exchange_rate NUMERIC NOT NULL CHECK (exchange_rate > 0),
        amount_etb NUMERIC NOT NULL CHECK (amount_etb > 0),
        payment_method TEXT NOT NULL,
        reference TEXT DEFAULT '',
        created_by TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        budget_allocation_id INTEGER,
        procurement_order_id INTEGER,
        budget_expenditure_id INTEGER
    , updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE finance_invoices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_number TEXT NOT NULL UNIQUE,
        invoice_type TEXT NOT NULL
            CHECK (invoice_type IN ('customer', 'supplier')),
        party_name TEXT NOT NULL,
        party_contact TEXT DEFAULT '',
        issue_date TEXT NOT NULL,
        due_date TEXT,
        currency TEXT NOT NULL DEFAULT 'ETB',
        total_amount NUMERIC NOT NULL CHECK (total_amount > 0),
        exchange_rate NUMERIC NOT NULL CHECK (exchange_rate > 0),
        total_etb NUMERIC NOT NULL CHECK (total_etb > 0),
        notes TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'Unpaid'
            CHECK (status IN ('Unpaid', 'Partially Paid', 'Paid', 'Cancelled')),
        created_by TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        budget_allocation_id INTEGER,
        procurement_order_id INTEGER
    , updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE finance_payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_id INTEGER NOT NULL,
        payment_date TEXT NOT NULL,
        amount NUMERIC NOT NULL CHECK (amount > 0),
        amount_etb NUMERIC NOT NULL CHECK (amount_etb > 0),
        payment_method TEXT NOT NULL,
        reference TEXT DEFAULT '',
        created_by TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (invoice_id) REFERENCES finance_invoices(id)
    );

CREATE TABLE procurement_suppliers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        contact_person TEXT DEFAULT '',
        phone TEXT DEFAULT '',
        email TEXT DEFAULT '',
        address TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    , updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE procurement_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_number TEXT NOT NULL UNIQUE,
        department TEXT NOT NULL DEFAULT 'general',
        item_name TEXT NOT NULL,
        quantity REAL NOT NULL CHECK (quantity > 0),
        unit TEXT NOT NULL DEFAULT 'pcs',
        estimated_cost REAL NOT NULL DEFAULT 0 CHECK (estimated_cost >= 0),
        supplier_id INTEGER,
        requested_by INTEGER NOT NULL,
        requested_by_name TEXT NOT NULL,
        justification TEXT NOT NULL DEFAULT '',
        notes TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'Pending'
            CHECK (status IN ('Draft', 'Pending', 'Approved', 'Rejected')),
        submitted_at TEXT,
        approval_request_id INTEGER,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        budget_allocation_id INTEGER, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (supplier_id) REFERENCES procurement_suppliers(id)
    );

CREATE TABLE procurement_orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_number TEXT NOT NULL UNIQUE,
        supplier_id INTEGER NOT NULL,
        item_name TEXT NOT NULL,
        quantity REAL NOT NULL CHECK (quantity > 0),
        unit TEXT NOT NULL DEFAULT 'pcs',
        unit_price REAL NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
        total_cost REAL NOT NULL DEFAULT 0 CHECK (total_cost >= 0),
        expected_date TEXT,
        status TEXT NOT NULL DEFAULT 'Ordered'
            CHECK (status IN (
                'Ordered', 'Partially Received', 'Received', 'Cancelled'
            )),
        created_by INTEGER NOT NULL,
        created_by_name TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        request_id INTEGER,
        issued_at TEXT,
        budget_allocation_id INTEGER,
        invoiced_at TEXT, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (supplier_id) REFERENCES procurement_suppliers(id)
    );

CREATE TABLE procurement_request_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        line_number INTEGER NOT NULL DEFAULT 1,
        item_name TEXT NOT NULL,
        quantity REAL NOT NULL CHECK (quantity > 0),
        unit TEXT NOT NULL DEFAULT 'pcs',
        unit_price REAL NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
        line_total REAL NOT NULL DEFAULT 0 CHECK (line_total >= 0),
        notes TEXT DEFAULT '',
        FOREIGN KEY (request_id) REFERENCES procurement_requests(id)
            ON DELETE CASCADE
    );

CREATE TABLE procurement_deliveries (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_id INTEGER NOT NULL,
        delivery_date TEXT NOT NULL,
        quantity REAL NOT NULL CHECK (quantity > 0),
        notes TEXT NOT NULL DEFAULT '',
        received_by INTEGER,
        received_by_name TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (order_id) REFERENCES procurement_orders(id)
    );

CREATE INDEX idx_finance_tx_alloc ON finance_transactions(budget_allocation_id);
CREATE INDEX idx_finance_tx_date ON finance_transactions(transaction_date);
CREATE INDEX idx_finance_tx_expenditure ON finance_transactions(budget_expenditure_id);
CREATE INDEX idx_finance_tx_type ON finance_transactions(transaction_type, transaction_date);
CREATE INDEX idx_finance_inv_alloc ON finance_invoices(budget_allocation_id);
CREATE INDEX idx_finance_inv_issue ON finance_invoices(issue_date);
CREATE INDEX idx_finance_inv_status ON finance_invoices(status);
CREATE INDEX idx_finance_pay_invoice ON finance_payments(invoice_id);
CREATE INDEX idx_proc_req_creator ON procurement_requests(requested_by, created_at);
CREATE INDEX idx_proc_req_department ON procurement_requests(department, id DESC);
CREATE INDEX idx_proc_req_status ON procurement_requests(status);
CREATE INDEX idx_po_request ON procurement_orders(request_id);
CREATE INDEX idx_proc_order_created ON procurement_orders(created_at);
CREATE INDEX idx_proc_order_status ON procurement_orders(status);
CREATE INDEX idx_pr_items_request ON procurement_request_items(request_id);
CREATE INDEX idx_pr_delivery_order ON procurement_deliveries(order_id);
